import Checkbox from '@jetbrains/ring-ui-built/components/checkbox/checkbox'
import plur from 'plur'
import {memo, Suspense, useMemo} from 'react'
import {graphql, useFragment, usePreloadedQuery} from 'react-relay'
import type {PreloadedQuery} from 'react-relay/relay-hooks/EntryPointTypes'

import {useSyncedBooleanQueryParam} from '../../../../hooks/routes'
import {useProjectData} from '../../../../hooks/useEntity'
import {useThrottle} from '../../../../hooks/useThrottle'
import {restApi} from '../../../../services/rest'
import type {BuildId} from '../../../../types'
import {toBuildId} from '../../../../types'
import {notNull} from '../../../../utils/guards'
import {UserProperties} from '../../../../utils/userProperties'
import ContentPanel from '../../../common/ContentPanel/ContentPanel'
import {useSequenceLoaderReadyHandler} from '../../../common/SequenceLoader/SequenceLoader.hooks'
import type {SeqProps} from '../../../common/SequenceLoader/SequenceLoader.types'
import {TreeEntityType} from '../BuildProblems.types'
import BuildProblemsTree from '../BuildProblemsTree/BuildProblemsTree.container'
import {buildProblemsTreeContextDefaultValue} from '../BuildProblemsTree/BuildProblemsTree.context'

import type {BuildProblemsPreviewDependencyIdsFragment$key} from './__generated__/BuildProblemsPreviewDependencyIdsFragment.graphql'
import type {BuildProblemsPreviewQuery} from './__generated__/BuildProblemsPreviewQuery.graphql'
import {useBuildProblemsSubscriptions} from './BuildProblemsPreview.hooks'
import {buildProblemsPreviewQuery} from './BuildProblemsPreview.queries'
import {
  getProblemOccurrencesLocator,
  getProblemRootCausesLocator,
  getRootNode,
} from './BuildProblemsPreview.utils'

import styles from './BuildProblemsPreview.module.css'

const dependencyIdsFragment = graphql`
  fragment BuildProblemsPreviewDependencyIdsFragment on Builds {
    build {
      id
    }
  }
`

type Props = SeqProps & {
  buildId: BuildId
  buildProblemsPreviewQueryRef: PreloadedQuery<BuildProblemsPreviewQuery>
}
const THROTTLER_TIMEOUT = 10000

function BuildProblemsPreview({buildId, buildProblemsPreviewQueryRef}: Props) {
  const projectId = useProjectData({buildId}, project => project?.id)

  const problemsLocator = getProblemOccurrencesLocator(buildId)
  const rootCausesLocator = getProblemRootCausesLocator(buildId)
  const buildsKey: BuildProblemsPreviewDependencyIdsFragment$key | null =
    usePreloadedQuery(buildProblemsPreviewQuery, buildProblemsPreviewQueryRef)?.builds ?? null
  const builds = useFragment(dependencyIdsFragment, buildsKey)?.build
  const buildIds = useMemo(() => builds?.map(build => build.id).filter(notNull) ?? [], [builds])

  const [hideProblemsFromDependencies, toggleHideProblemsFromDependencies] =
    useSyncedBooleanQueryParam({
      param: 'hideProblemsFromDependencies',
      userProperty: UserProperties.HIDE_PROBLEMS_FROM_DEPENDENCIES,
    })

  const endpoint = buildProblemsTreeContextDefaultValue.getEndpoint()

  const {
    countProblems = 0,
    treeProblemsReady,
    refetch: refetchProblemOccurenceTree,
  } = restApi.endpoints.getProblemOccurrenceTree.useQuery(
    {
      endpoint,
      locator: problemsLocator,
      treeLocator: problemsLocator,
    },
    {
      selectFromResult: ({data}) => ({
        countProblems: getRootNode(data?.tree.node)?.count,
        treeProblemsReady: data != null,
      }),
    },
  )
  const fetchProblemOccurrenceTreeHandler = useThrottle(
    refetchProblemOccurenceTree,
    THROTTLER_TIMEOUT,
  )
  const {
    countRootCauses = 0,
    newFailedCountRootCauses = 0,
    hasRootCausesInOtherBuilds,
    treeRootCausesReady,
    refetch: refetchRootCausesTree,
  } = restApi.endpoints.getProblemOccurrenceTree.useQuery(
    {
      endpoint,
      locator: rootCausesLocator,
      treeLocator: rootCausesLocator,
    },
    {
      selectFromResult: ({data}) => {
        const {count, newFailedCount} = getRootNode(data?.tree.node) ?? {}
        return {
          countRootCauses: count,
          newFailedCountRootCauses: newFailedCount,
          hasRootCausesInOtherBuilds: data?.tree.node?.some(
            node =>
              node.type === TreeEntityType.BUILD && toBuildId(node.name) !== toBuildId(buildId),
          ),
          treeRootCausesReady: data != null,
        }
      },
    },
  )
  const fetchRootCausesTreeHandler = useThrottle(refetchRootCausesTree, THROTTLER_TIMEOUT)

  const isReady = treeProblemsReady && treeRootCausesReady
  useSequenceLoaderReadyHandler(isReady)

  const locator =
    countProblems > 0 && hideProblemsFromDependencies ? problemsLocator : rootCausesLocator

  const labelId = 'buildProblemsPreview'
  const renderHeading = useMemo(() => {
    const title = `${countRootCauses} Build ${plur('Problem', countRootCauses)}`
    const countOfNew = newFailedCountRootCauses > 0 ? `, ${newFailedCountRootCauses} new` : ''
    return <span id={labelId}>{`${title}${countOfNew}`}</span>
  }, [countRootCauses, newFailedCountRootCauses])

  const renderHeaderSnippet = useMemo(
    () =>
      countProblems > 0 &&
      hasRootCausesInOtherBuilds && (
        <Checkbox
          containerClassName={styles.hideProblemsFromDependencies}
          checked={hideProblemsFromDependencies}
          onChange={() => toggleHideProblemsFromDependencies(!hideProblemsFromDependencies)}
        >
          {'Hide from dependencies'}
        </Checkbox>
      ),
    [
      countProblems,
      hasRootCausesInOtherBuilds,
      hideProblemsFromDependencies,
      toggleHideProblemsFromDependencies,
    ],
  )

  const renderContent = useMemo(
    () => (
      <Suspense>
        <BuildProblemsTree
          labelId={labelId}
          key={locator}
          locator={locator}
          projectId={projectId}
          buildId={buildId}
        />
      </Suspense>
    ),
    [locator, projectId, buildId],
  )
  useBuildProblemsSubscriptions({buildIds: [buildId], handler: fetchProblemOccurrenceTreeHandler})
  useBuildProblemsSubscriptions({buildIds, handler: fetchRootCausesTreeHandler})

  return isReady && countRootCauses > 0 ? (
    <ContentPanel
      errorHeading
      panelType={UserProperties.EXPAND_BUILD_PROBLEMS_SECTION}
      heading={renderHeading}
      headerSnippet={renderHeaderSnippet}
      content={renderContent}
      withBorder={false}
    />
  ) : null
}

export default memo(BuildProblemsPreview)
