import {Suspense} from 'react'
import {connect} from 'react-redux'

import {openDialog} from '../../../actions'
import type {State} from '../../../reducers/types'
import {getBuild, getBuildPinInfo, getBuildType} from '../../../selectors'

import BuildPinInfo from './BuildPinInfo'
import type {OwnProps, StateProps, Props} from './BuildPinInfo.types'

const actionCreators = {
  openDialogAction: openDialog,
}

const mapStateToProps = (state: State, props: OwnProps): StateProps => {
  const build = getBuild(state, props.buildId)
  const {text, buildTypeId, user, timestamp} = getBuildPinInfo(state, props.buildId) || {}
  const {projectId} = getBuildType(state, buildTypeId) || {}
  return {
    user,
    pinned: build?.pinned === true,
    text,
    timestamp,
    projectId,
    buildTypeId,
    isFinishedBuild: build?.state === 'finished',
  }
}

export default connect(
  mapStateToProps,
  actionCreators,
)(function BuildPinInfoContainer(props: Props) {
  return (
    <Suspense>
      <BuildPinInfo {...props} />
    </Suspense>
  )
})
