import Button from '@jetbrains/ring-ui-built/components/button/button'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import * as React from 'react'

import TransformText from '../../../containers/TransformText'
import {usePermission} from '../../../hooks/usePermission'
import {useDistanceToNow} from '../../../hooks/useTimeSelector'
import {useUserDisplayName} from '../../../hooks/useUserDisplayName'
import {DialogType, Permission, stringifyId} from '../../../types'

import type {Props} from './BuildPinInfo.types'

import styles from './BuildPinInfo.module.css'

const MIN_LINES = 4

function BuildPinInfo({
  buildTypeId,
  buildId,
  timestamp,
  user,
  text,
  className,
  isFinishedBuild,
  projectId,
  pinned,
  compact,
  withIcon,
  openDialogAction,
}: Props) {
  const canPin = usePermission(Permission.PIN_UNPIN_BUILD, projectId)
  const isPinnable = isFinishedBuild && canPin
  const handleComment = React.useCallback(
    () => openDialogAction(stringifyId(buildId), DialogType.EDIT_PIN_COMMENT),
    [buildId, openDialogAction],
  )
  const handleUnpin = React.useCallback(
    () => openDialogAction(stringifyId(buildId), DialogType.PIN),
    [buildId, openDialogAction],
  )
  const timestampFromNow = useDistanceToNow(timestamp)
  const userDisplayName = useUserDisplayName(user, true)

  return pinned ? (
    <div className={classNames(className, styles.wrapper)}>
      {withIcon === true && <SvgIcon icon="pin-filled" className={styles.icon} />}
      <div>
        <span className={styles.userInfo}>
          {'Pinned'}
          {userDisplayName != null ? ` by ${userDisplayName}` : ''}
        </span>
        {timestampFromNow != null && (
          <span className={styles.timestamp}>{`${timestampFromNow}${!text ? '' : ':'}`}</span>
        )}
        {text != null && (
          <TransformText
            text={text}
            lines={compact ? MIN_LINES : null}
            lineHeight={16}
            buildTypeId={buildTypeId}
          />
        )}
        {isPinnable && (
          <div>
            <Button className={styles.button} onClick={handleUnpin} inline>
              {'Unpin'}
            </Button>
            <Button className={styles.button} onClick={handleComment} inline>
              {text != null ? 'Edit pin message...' : 'Add pin message...'}
            </Button>
          </div>
        )}
      </div>
    </div>
  ) : null
}

export default React.memo(BuildPinInfo)
