import {useCallback, useMemo} from 'react'
import type {PreloadedQuery} from 'react-relay/relay-hooks/EntryPointTypes'

import {useAppSelector} from '../../../../hooks/react-redux'
import {useRefetchablePreloadedQuery} from '../../../../hooks/relay/useRefetchablePreloadedQuery'
import {getBuildLocator} from '../../../../rest/locators'
import {getOverviewHref} from '../../../../routes'
import {
  getBuild,
  getPipelineRunIdFromBuildId,
  getPipelineIdFromBuildId,
} from '../../../../selectors'
import {type BuildId} from '../../../../types'
import {useSequenceLoaderReadyHandler} from '../../SequenceLoader/SequenceLoader.hooks'

import type {SnapshotDependenciesCountersQuery} from './__generated__/SnapshotDependenciesCountersQuery.graphql'
import SnapshotDependenciesCounters from './SnapshotDependenciesCounters'
import {useSnapshotDependenciesCounters} from './SnapshotDependenciesCounters.hooks'
import {
  getSnapshotDependenciesCountersVariables,
  snapshotDependenciesCountersQuery,
} from './SnapshotDependenciesCounters.queries'

type Props = {
  buildId?: BuildId | null | undefined
  queryRef: PreloadedQuery<SnapshotDependenciesCountersQuery>
}

export default function SnapshotDependenciesCountersContainer({buildId, queryRef}: Props) {
  const [data, refetch] = useRefetchablePreloadedQuery(snapshotDependenciesCountersQuery, queryRef)
  const doRefetch = useCallback(() => {
    refetch(getSnapshotDependenciesCountersVariables(getBuildLocator(buildId)))
  }, [buildId, refetch])

  const builds = useMemo(() => data?.builds ?? null, [data?.builds])

  useSequenceLoaderReadyHandler(true)
  const overallCount = builds?.count ?? 0
  const {
    finishedFailed,
    finishedSuccessful,
    queued,
    canceled,
    failedToStart,
    runningFailed,
    runningSuccessful,
    overdue,
  } = useSnapshotDependenciesCounters(builds, doRefetch)
  const buildTypeId = useAppSelector(state => getBuild(state, buildId)?.buildType)
  const pipelineId = useAppSelector(state => getPipelineIdFromBuildId(state, buildId))
  const runId = useAppSelector(state => getPipelineRunIdFromBuildId(state, buildId))
  const query = pipelineId == null ? `?buildTab=dependencies` : ''

  return (
    <SnapshotDependenciesCounters
      overallCount={overallCount}
      finishedFailed={finishedFailed}
      finishedSuccessful={finishedSuccessful}
      queued={queued}
      canceled={canceled}
      failedToStart={failedToStart}
      runningFailed={runningFailed}
      runningSuccessful={runningSuccessful}
      overdue={overdue}
      title={pipelineId != null ? `Jobs` : 'Dependencies'}
      filtered={!pipelineId}
      dependenciesTabLink={`${getOverviewHref({
        buildId,
        buildTypeId,
        pipelineId,
        runId,
      })}${query}`}
    />
  )
}
