import classNames from 'classnames'
import {memo} from 'react'

import Icon from '../../Icon/Icon'
import LinkWithIcon from '../../LinkWithIcon/LinkWithIcon'
import RouterLink from '../../RouterLink/RouterLink'
import RouterLinkWrapper from '../../RouterLinkWrapper/RouterLinkWrapper'

import styles from './SnapshotDependenciesCounters.module.css'

function dependenciesTabLinkWithStatus(tabLink: string, filtered?: boolean) {
  return (status: string) => `${tabLink}${filtered ? `&mode=list&state=${status}` : ''}`
}

type StatusGroups = {
  finishedSuccessful: number
  runningSuccessful: number
  finishedFailed: number
  runningFailed: number
  failedToStart: number
  canceled: number
  queued: number
  overallCount: number
  overdue: number
}

type StatusesProps = {
  dependenciesTabLink: string
  filtered?: boolean
} & StatusGroups

function Statuses({
  finishedSuccessful,
  runningSuccessful,
  finishedFailed,
  runningFailed,
  failedToStart,
  canceled,
  queued,
  overdue,
  dependenciesTabLink,
  filtered,
}: StatusesProps) {
  const statusLink = dependenciesTabLinkWithStatus(dependenciesTabLink, filtered)
  const finished = finishedSuccessful + finishedFailed
  let finishedNode = null
  if (finished > 0) {
    const hrefSuccessful = statusLink('successful')
    const hrefFailed = statusLink('failed')
    finishedNode = (
      <span>
        {`${finished} finished: `}
        <RouterLink to={hrefFailed} className={styles.failed}>
          {`${finishedFailed} failed`}
        </RouterLink>
        {', '}
        <RouterLink to={hrefSuccessful} className={styles.successful}>
          {`${finishedSuccessful} successful`}
        </RouterLink>
      </span>
    )
    if (finished === finishedFailed) {
      finishedNode = (
        <RouterLink to={hrefFailed} className={styles.failed}>
          {`${finished} finished with failure`}
        </RouterLink>
      )
    }
    if (finished === finishedSuccessful) {
      finishedNode = (
        <RouterLink to={hrefSuccessful} className={styles.successful}>
          {`${finished} finished successfully`}
        </RouterLink>
      )
    }
  }

  const running = runningSuccessful + runningFailed
  let runningNode = null
  if (running > 0) {
    const link = statusLink('running')
    runningNode = (
      <span>
        <Icon name="running_static" className={classNames(styles.icon, styles.running)} />
        <RouterLink to={link} className={styles.text}>{`${running} running`}</RouterLink>
        {': '}
        <span className={styles.failed}>{`${runningFailed} failed`}</span>
        {', '}
        <span className={styles.successful}>{`${runningSuccessful} still successful`}</span>
      </span>
    )
    if (running === runningFailed) {
      runningNode = (
        <RouterLinkWrapper>
          <LinkWithIcon icon="running_static" href={link} className={styles.failed}>
            {`${running} failed and running`}
          </LinkWithIcon>
        </RouterLinkWrapper>
      )
    }
    if (running === runningSuccessful) {
      runningNode = (
        <RouterLinkWrapper>
          <LinkWithIcon icon="running_static" href={link} className={styles.successful}>
            {`${running} running and still successful`}
          </LinkWithIcon>
        </RouterLinkWrapper>
      )
    }
  }

  const failedToStartNode =
    failedToStart > 0 ? (
      <RouterLinkWrapper>
        <LinkWithIcon icon="failedToStart" href={statusLink('failedToStart')}>
          {`${failedToStart} failed to start`}
        </LinkWithIcon>
      </RouterLinkWrapper>
    ) : null

  const canceledNode =
    canceled > 0 ? (
      <RouterLinkWrapper>
        <LinkWithIcon icon="canceled" href={statusLink('canceled')}>
          {`${canceled} canceled`}
        </LinkWithIcon>
      </RouterLinkWrapper>
    ) : null

  const queuedNode =
    queued > 0 ? (
      <RouterLinkWrapper>
        <LinkWithIcon icon="queued" href={statusLink('queued')}>
          {`${queued} in queue`}
        </LinkWithIcon>
      </RouterLinkWrapper>
    ) : null

  const overtimedNode =
    overdue > 0 ? (
      <RouterLinkWrapper>
        <LinkWithIcon
          iconInnerClassName={styles.overtimeIcon}
          icon="overtime"
          href={statusLink('running')}
          tailLength={3}
        >
          {`${overdue} overdue`}
        </LinkWithIcon>
      </RouterLinkWrapper>
    ) : null

  return (
    <td className={styles.statuses}>
      {finishedNode}
      {runningNode}
      {failedToStartNode}
      {canceledNode}
      {queuedNode}
      {overtimedNode}
    </td>
  )
}

type SnapshotDependenciesCountersProps = {
  dependenciesTabLink: string
  title?: string
  filtered?: boolean
} & StatusGroups

function SnapshotDependenciesCounters({
  dependenciesTabLink,
  title = 'Dependencies',
  filtered = true,
  ...stats
}: SnapshotDependenciesCountersProps) {
  return stats.overallCount > 0 ? (
    <tr>
      <th>
        <RouterLink to={dependenciesTabLink} className={styles.headingLink}>
          {title}
        </RouterLink>
      </th>
      <Statuses dependenciesTabLink={dependenciesTabLink} filtered={filtered} {...stats} />
    </tr>
  ) : null
}

export default memo(SnapshotDependenciesCounters)
